DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:PSD 148", "old_status": "worked_needs_crop", "status": "ready", "question_id": "eab9d063-b8c5-5529-b546-4723e008db79", "stem": "A distinct arrangement of all the letters of PHARMACY is selected uniformly at random. What is the probability that the two As are adjacent?", "choices": [{"key": "A", "text": "0.1"}, {"key": "B", "text": "0.25"}, {"key": "C", "text": "0.7"}, {"key": "D", "text": "0.78"}], "type": "mcq", "correct": "B", "explanation": "There are 8!/2! = 20160 distinct arrangements. When the As are adjacent, treat AA as one block with the other six letters: 7! = 5040 arrangements. Thus the probability is 5040/20160 = 1/4 = 0.25.", "topic": "Statistics, Probability & Data Analysis", "note": "Source page 257 visually checked; isolated complete question and verified all options.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 257, "extra_sources": []}, {"id": "clean:PSD 182", "old_status": "worked_needs_crop", "status": "ready", "question_id": "051734f8-6ea7-527e-abda-ac6d4796a5ea", "stem": "The chart shows cars sold, in thousands, starting in 2010. Between which two years was the decrease approximately 11%?", "choices": [{"key": "A", "text": "2012–2013"}, {"key": "B", "text": "2013–2014"}, {"key": "C", "text": "2014–2015"}, {"key": "D", "text": "2015–2016"}], "type": "mcq", "correct": "C", "explanation": "Sales fell from 9 thousand in 2014 to 8 thousand in 2015. The percentage decrease was (9 − 8)/9 × 100% ≈ 11.11%. The other listed intervals show a larger decrease or an increase.", "topic": "Statistics, Probability & Data Analysis", "note": "Source page 277 visually checked; isolated complete question and verified all options.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 277, "extra_sources": [], "crop": {"page": 277, "rect": [135, 130, 552, 397]}, "assets": {"figure": "data:image/jpeg;base64,"}}, {"id": "clean:PSD 192", "old_status": "worked_needs_crop", "status": "ready", "question_id": "d6befa48-4be0-5711-ab8b-df709eac7626", "stem": "An item originally costs $500. Its price is reduced by 15%, then a 15% packaging and delivery charge is added to the reduced price. What is the final cost?", "choices": [{"key": "A", "text": "$500"}, {"key": "B", "text": "$361.25"}, {"key": "C", "text": "$350"}, {"key": "D", "text": "$488.75"}], "type": "mcq", "correct": "D", "explanation": "The discounted price is 500 × 0.85 = $425. Adding 15% of that price gives 425 × 1.15 = $488.75. Equal percentage decreases and increases do not cancel because they use different bases.", "topic": "Statistics, Probability & Data Analysis", "note": "Source page 284 visually checked; isolated complete question and verified all options.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 284, "extra_sources": []}, {"id": "clean:PAM 056", "old_status": "worked_needs_crop", "status": "ready", "question_id": "ad57cfed-9238-546a-8645-4862b064b9bd", "stem": "What is the minimum of \\(2x^2-8\\) for real x?", "choices": [{"key": "A", "text": "0"}, {"key": "B", "text": "8"}, {"key": "C", "text": "4"}, {"key": "D", "text": "−8"}], "type": "mcq", "correct": "D", "explanation": "For real x, \\(x^2\\ge0\\), so \\(2x^2-8\\ge-8\\). Equality occurs at x = 0, making −8 the minimum.", "topic": "Polynomials & Quadratic Functions", "note": "Source page 341 visually checked; isolated complete question and verified all options.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 341, "extra_sources": []}, {"id": "clean:PAM 068", "old_status": "worked_needs_crop", "status": "ready", "question_id": "cfdc7f2e-9457-510a-b1ed-36ca2db72e49", "stem": "Which is a factor of \\(3x^2+11x+10\\)?", "choices": [{"key": "A", "text": "3x − 5"}, {"key": "B", "text": "x − 2"}, {"key": "C", "text": "3x + 5"}, {"key": "D", "text": "x + 5"}], "type": "mcq", "correct": "C", "explanation": "Factor by grouping: \\(3x^2+6x+5x+10=3x(x+2)+5(x+2)=(3x+5)(x+2)\\). Therefore 3x + 5 is a factor.", "topic": "Polynomials & Quadratic Functions", "note": "Source page 348 visually checked; isolated complete question and verified all options.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 348, "extra_sources": []}, {"id": "clean:PAM 092", "old_status": "worked_needs_crop", "status": "ready", "question_id": "f28c808c-bddd-78d6-ccaa-4c08b8d60f10", "stem": "If \\(f(x)=x^3-3x\\) and \\(g(x)=x-4\\), what is \\(f(g(1))\\)?", "choices": [{"key": "A", "text": "−27"}, {"key": "B", "text": "−21"}, {"key": "C", "text": "−18"}, {"key": "D", "text": "−12"}], "type": "mcq", "correct": "C", "explanation": "First \\(g(1)=1-4=-3\\). Then \\(f(-3)=(-3)^3-3(-3)=-27+9=-18\\).", "topic": "Functions, Transformations & Graphs", "note": "Source page 363 visually checked; isolated complete question and verified all options.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 363, "extra_sources": [], "before": {"stem": "If f(x) = x³ − 3x and g(x) = x − 4, then f(g(1)) =", "choices": [{"key": "A", "text": "−27"}, {"key": "B", "text": "−21"}, {"key": "C", "text": "−18"}, {"key": "D", "text": "−12"}], "correct": "C", "explanation": "Answer key transcribed from the complete printed source key and structurally validated against the listed choices."}}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='source_review_20260928' AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_20260928','source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
